import json,re
from pathlib import Path
B=Path('data');q=json.loads((B/'legal/domains/law-questions.json').read_text());items=json.loads(Path('dist/legal-bases.json').read_text())['items'];texts={};refs={};caveats={}
def a(ids,text,*sources,caveat=None):
 for i in ids:
  texts[i]=text;refs[i]=list(sources)
  if caveat:caveats[i]=caveat
# Obliczenia: jawne działania zamiast powtórzenia klucza.
a([20],'Przejście od stanu przeciętnego do bardzo dobrego obejmuje cały zakres wpływu lokalizacji: 15 zł. Cena nieruchomości porównawczej wymaga zwiększenia o 15 zł, ponieważ jej lokalizacja jest gorsza od wycenianej.')
a([66],'Przy równych odstępach trzech stanów różnica między stanami sąsiednimi to 500/2 = 250 zł, a między skrajnymi 500 zł. Znak poprawki zależy od kierunku porównania: lepsza nieruchomość wzorcowa oznacza poprawkę ujemną, gorsza dodatnią.',caveat='Założenie równych odstępów stanów musi wynikać z przyjętego modelu; samo wyliczenie trzech nazw stanów go nie dowodzi.')
a([136,231,240,452,695],'Rozpiętość cen wynosi 3000 − 2000 = 1000 zł/m². Cecha odpowiada za 200 zł/m² tej różnicy, zatem jej waga wynosi 200/1000 × 100% = 20%.')
a([324],'Zakres wpływu cechy pomiędzy stanami skrajnymi jest sumą wpływu dwóch kolejnych przejść: 15% + 16% = 31%. Nie uśredniamy tych wartości, ponieważ dotyczą różnych odcinków jednej skali.')
a([266,558],'Przyrost ceny wynosi 1100 − 1000 = 100 zł, czyli 10% ceny początkowej. Od marca do maja upływają dwa miesiące, więc liniowy trend miesięczny to 10%/2 = 5%.',caveat='Wynik 5% dotyczy modelu liniowego. Przy kapitalizacji składanej miesięczna stopa wyniosłaby √1,10 − 1 ≈ 4,88%.')
a([480,500,719],'W liniowym modelu zmiany cen: 1000 × (1 + 2 × 0,02) = 1040 zł/m². Dwa miesiące dodają łącznie 4% ceny początkowej.',caveat='Przy naliczaniu składanym wynik wyniósłby 1000 × 1,02² = 1040,40 zł. Klucz przyjmuje liniowy trend cenowy.')
a([399],'Najpierw efektywny dochód brutto: 10 000 × 0,90 = 9000 zł. Wydatki stanowią 10% tej kwoty, czyli 900 zł. Dochód operacyjny netto wynosi 9000 − 900 = 8100 zł.')
a([635],'Efektywny dochód brutto to DON + wydatki = 40 000 + 5000 = 45 000 zł. Po stracie 10% pozostaje 90% dochodu potencjalnego, więc PDB = 45 000/0,90 = 50 000 zł.')
a([522],'Stopa dochodu z całej nieruchomości wynosi 48 000/480 000 = 0,10, czyli 10%. Kwota hipoteki nie zmienia tego ilorazu. Do obliczenia stopy zwrotu z kapitału własnego potrzebne byłyby dodatkowo koszty obsługi długu.')
a([543],'Zakres cen to 270 − 220 = 50 zł/m². Wpływ uzbrojenia wynosi 30% × 50 = 15 zł/m². Poprawka między skrajnymi stanami może więc wynieść +15 albo −15 zł/m², zależnie od kierunku porównania.')
a([540],'Projekt spełnia podany próg rentowności: IRR = 15% przewyższa wymaganą stopę 10%. Dla typowego strumienia z jednorazowym nakładem początkowym oznacza to dodatnie NPV przy stopie 10%.',caveat='Reguła wymaga ostrożności przy nietypowych strumieniach, dla których istnieje kilka IRR albo nie ma żadnej.')
a([44,539],'Asymetria oznacza, że rozkład cen nie jest symetryczny wokół średniej. Kierunek ma znaczenie: przy prawostronnej asymetrii długi ogon wysokich cen zwykle podciąga średnią, a przy lewostronnej działa odwrotnie.',caveat='Samo słowo „asymetryczny” nie pozwala ustalić, czy częstsze są ceny wyższe czy niższe od średniej. Dwie wskazane odpowiedzi opisują różne możliwe kierunki, a nie jeden ustalony rozkład.')
a([180],'Stopa inflacji opisuje procentową zmianę ogólnego poziomu cen w czasie: (poziom cen końcowy/poziom cen początkowy − 1) × 100%. Dotyczy koszyka dóbr i usług, nie pojedynczej ceny nieruchomości.')
a([330],'Rosnące ceny zmniejszają ilość dóbr, którą można kupić za daną kwotę, czyli siłę nabywczą pieniądza. Wyższa oczekiwana inflacja może też zmniejszać skłonność do trzymania nieoprocentowanych zasobów pieniężnych.',caveat='Spadek popytu na pieniądz nie jest bezwarunkowym skutkiem każdej inflacji: zależy także od dochodu, stóp procentowych i przyjętej definicji popytu.')
a([332],'Prosta roczna stopa zwrotu porównuje roczny zysk z nakładem początkowym: zysk roczny/nakłady inwestycyjne. Nie uwzględnia rozkładu przepływów w czasie ani wartości pieniądza w czasie, które uwzględnia np. IRR.')
a([360],'Rentowność do wykupu jest stopą dyskontową zrównującą bieżącą cenę obligacji z sumą zdyskontowanych kuponów i kwoty wykupu. Jest więc IRR strumienia: wydatek na zakup, późniejsze kupony i wykup.')
a([232,451],'Nieruchomości są zróżnicowane i nieruchome, a informacje o transakcjach bywają niepełne. Podaż reaguje wolno, ponieważ budowa i zmiana zagospodarowania wymagają czasu. Te cechy utrudniają szybkie wyrównywanie cen oraz popytu i podaży.',caveat='Elastyczność popytu zależy od segmentu rynku, okresu analizy i dostępności substytutów; niska elastyczność nie jest stałą dla każdej nieruchomości.')
a([433,557,752],'Cena równowagi odpowiada przecięciu krzywych popytu i podaży: przy tej cenie wielkość oferowana jest równa wielkości, którą nabywcy chcą i mogą kupić. Wyższa cena zwykle wywołuje nadwyżkę podaży, niższa niedobór.')
a([556],'Dodatnia elastyczność mieszana oznacza, że wzrost ceny dobra A zwiększa popyt na dobro B. Nabywcy zastępują droższe A dobrem B, dlatego dobra są substytutami. Dla dóbr komplementarnych relacja jest zwykle odwrotna.')
a([453],'Mały błąd resztowy oznacza niewielkie odchylenia obserwacji od przewidywań modelu. Niski współczynnik indeterminacji oznacza małą część zmienności niewyjaśnioną przez model, czyli wysokie R².',caveat='Dobre dopasowanie w próbie nie wystarcza do oceny poprawności modelu ani jakości prognoz poza próbą.')
a([396],'Ryzyko lokalizacyjne dotyczy otoczenia i położenia, rynkowe zmian popytu, podaży i cen, a płynności trudności szybkiej sprzedaży bez znacznej obniżki ceny. Mogą występować jednocześnie i wymagają odrębnej oceny.')
a([612],'Zmienna stopa kredytu może zwiększyć ratę po wzroście stóp rynkowych. To ryzyko stopy procentowej; zwiększone obciążenie może następnie pogorszyć zdolność kredytobiorcy do spłaty i zwiększyć ryzyko kredytowe.',caveat='Ryzyko stopy procentowej i ryzyko kredytowe są odrębnymi kategoriami. Jedno może wpływać na drugie; ich utożsamienie w kluczu jest uproszczeniem.')
a([697],'Wybór najtańszego sposobu wytworzenia zadanej produkcji opisuje efektywność kosztową: spośród dostępnych technik wybiera się tę o najmniejszym koszcie.',caveat='Ścisła efektywność techniczna oznacza brak marnotrawstwa nakładów, a nie koniecznie najniższy koszt przy danych cenach czynników. Pytanie miesza te pojęcia.')
a([578,723],'W modelu kapitalizacji dochodu rosnącego stałym tempem stopa kapitalizacji R = r − g, gdzie r to stopa dyskontowa, a g tempo trwałego wzrostu dochodu. Dodatnie g powoduje, że R jest niższa od r.',caveat='Dodatni wzrost nie dowodzi, że stopa dyskontowa sama wzrośnie lub kapitalizacji sama spadnie w czasie; chodzi o relację przy pozostałych założeniach stałych.')
a([284],'Rynek finansowy obejmuje instrumenty, takie jak obligacje i akcje, oraz instytucje pośredniczące, np. banki i fundusze inwestycyjne. Instrument jest przedmiotem obrotu, a bank lub fundusz uczestnikiem tego rynku.')
# Metodyka wyceny i kosztorysowania.
a([135],'Waga określa, jaką część całkowitego zróżnicowania cen przypisujemy danej cesze. W modelu poprawek kwotowych waga pomnożona przez rozpiętość cen daje maksymalny zakres poprawki za tę cechę.')
a([48,383],'Przy zbyt małej liczbie lokalnych transakcji same dane lokalne mogą nie wystarczyć do wiarygodnego oszacowania wag. Pomocne są badania preferencji nabywców i analiza porównywalnych rynków, z uzasadnieniem ich podobieństwa.',caveat='Nie należy automatycznie przenosić wag z dowolnego regionu: muszą odpowiadać badanemu segmentowi i okresowi.')
a([87],'Opłata roczna za użytkowanie wieczyste obciąża korzystanie z gruntu i może pomniejszać dochód osiągany z nieruchomości. Przy modelowaniu przepływów trzeba ustalić, kto ją faktycznie ponosi i czy nie została już ujęta w innej pozycji kosztów.')
a([111],'Czynsz umowny wynika z konkretnej umowy, która może obowiązywać na czas oznaczony lub nieoznaczony. Czynsz rynkowy jest natomiast oszacowaniem możliwej stawki w warunkach rynkowych; nie musi być równy kwocie zapisanej w istniejącej umowie.','kc:659')
a([162,265,479],'Od potencjalnego dochodu brutto odejmuje się straty z pustostanów i nieściągalności czynszu, uzyskując efektywny dochód brutto. Dopiero od niego odejmuje się wydatki operacyjne, aby uzyskać DON. Stąd EDB = DON + wydatki operacyjne.')
a([361],'DON = efektywny dochód brutto − wydatki operacyjne. Pustostany uwzględnia się wcześniej, przy przejściu od dochodu potencjalnego do efektywnego; ponowne ich odjęcie zaniżyłoby DON.')
a([163],'Technika elementów scalonych grupuje roboty w większe elementy, np. fundamenty lub dach. Ich ilości trzeba mierzyć zgodnie z definicjami jednostek i zakresem robót w użytym katalogu, aby nie porównywać różnych zestawów prac.')
a([210],'Cena jednostkowa robót obejmuje składniki bezpośrednie: robociznę Rj, materiały Mj, pracę sprzętu Sj, a także koszty zakupu Kzj, koszty pośrednie Kpj i zysk Zj. Sumowanie daje kosztorysową cenę jednostki danej roboty.',caveat='Symbole i sposób doliczania narzutów należy odczytać zgodnie z konkretną publikacją kosztorysową; nie wolno podwójnie doliczyć kosztów zakupu.')
a([542],'W najmie typu netto ciężar wskazanych kosztów eksploatacji przechodzi na najemcę, dlatego czynsz podstawowy nie obejmuje całego kosztu użytkowania. Zakres kosztów należy zawsze ustalić z umowy.',caveat='Nazwy netto i brutto nie zastępują analizy umowy; w praktyce występują różne odmiany najmu netto.')
a([334],'Wartość nieruchomości z obiektem przeznaczonym do likwidacji można rozłożyć na wartość gruntu oraz saldo odzysku materiałów i kosztów rozbiórki. Jeżeli rozbiórka kosztuje więcej niż odzysk, saldo pomniejsza wartość gruntu.')
a([410],'Drzewa na działce budowlanej mogą zwiększać atrakcyjność albo utrudniać zabudowę. Wpływ na wartość rynkową ustala się na podstawie zachowań nabywców, a nie przez automatyczne dodanie kosztu sadzonek lub opłaty za usunięcie.')
a([398],'Wykaz sprostowań pozwala poprawić oczywistą omyłkę pisarską i zachować ślad zmiany. Jeżeli błąd wpływa na wynik wyceny, nie jest to wyłącznie korekta pisarska i wymaga ponownego merytorycznego opracowania.')
a([418],'Oględziny służą ustaleniu faktycznego stanu nieruchomości i sprawdzeniu danych wykorzystanych w wycenie. Ich przebieg, zakres oraz ewentualne ograniczenia powinny być opisane w operacie; same dane z rejestrów nie zastępują ustalenia stanu faktycznego.')
a([419,715],'Przy zabezpieczeniu wierzytelności należy wskazać obszary ryzyka dotyczące wycenianej nieruchomości i ich możliwy wpływ na wartość. To nie jest to samo co bankowa ocena zdolności kredytowej dłużnika.',caveat='Zakres i miejsce informacji w operacie należy odnieść do rozporządzenia obowiązującego w dacie sporządzenia wyceny; nie każde historyczne pytanie opisuje aktualną redakcję.')
a([436],'Dobór transakcji powinien zapewnić porównywalność nieruchomości i warunków rynkowych. Szczególne warunki mogą zniekształcać cenę, dlatego wymagają analizy ich wpływu, a nie mechanicznego traktowania każdej zarejestrowanej kwoty jako ceny rynkowej.')
a([502,698],'Odroczona zapłata lub wydanie nieruchomości mogą zmienić ekonomiczne warunki transakcji. Analiza powinna ustalić, czy cena została przez to zniekształcona i czy nadaje się do porównań.',caveat='Reguła odchylenia ceny przetargowej o 20% pochodzi z dawnego brzmienia rozporządzenia. Nie należy traktować jej jako uniwersalnej aktualnej zasady ani bez badania odrzucać każdej transakcji z odroczeniem.')
a([467],'Wskazany wynik 90 000 zł można odtworzyć jako 1000 m² × (100 − 0,10 × 100) zł/m². Sam taki rachunek nie wyjaśnia jednak, dlaczego Wk miałby obniżać cenę dokładnie w ten sposób.',*['ugn:69'],caveat='Cena sprzedaży gruntu użytkownikowi wieczystemu podlegała zmianom prawnym. Dane zadania i samo wskazanie Wk nie wystarczają do uznania wzoru za obowiązującą podstawę ceny; klucz wymaga sprawdzenia dla daty egzaminu.')
# Prawa rzeczowe, klucze wadliwe i skutki czynności.
a([26],'Służebność osobista jest ustanawiana na rzecz oznaczonej osoby fizycznej, natomiast gruntowa na rzecz właściciela innej nieruchomości. Samo posiadanie samoistne nie jest jednak ogólną podstawą roszczenia o ustanowienie służebności.','kc:285','kc:296',caveat='Nie potwierdzono twierdzenia, że każdy posiadacz samoistny może żądać służebności osobistej. Trzeba odróżnić możliwość umownego ustanowienia prawa od roszczenia o jego ustanowienie.')
a([38,331],'Oddanie nieruchomości najemcy lub dzierżawcy nie odbiera oddającemu posiadania samoistnego. Korzystający włada wówczas jako posiadacz zależny; samo wydanie rzeczy nie czyni go posiadaczem samoistnym.','kc:336','kc:337',caveat='Klucz oznacza również odpowiedź o staniu się posiadaczem samoistnym przez posiadacza zależnego. Teza ta nie wynika z opisanej czynności i jest sprzeczna z rozróżnieniem w KC.')
a([145],'KC wymaga formy pisemnej dla najmu nieruchomości lub pomieszczenia na czas dłuższy niż rok. Bez niej najem uważa się za zawarty na czas nieoznaczony; nie oznacza to automatycznej nieważności umowy.','kc:660',caveat='„Dłuższy niż rok” nie znaczy „co najmniej jeden rok”. Zaznaczona odpowiedź ma nieprecyzyjną granicę czasową.')
a([165,584],'Hipoteką można obciążyć użytkowanie wieczyste, a także wierzytelność już zabezpieczoną hipoteką. W drugim przypadku przedmiotem zabezpieczenia jest wierzytelność, nie sama hipoteka rozumiana jako samodzielny przedmiot obrotu.','kw:65',caveat='Odpowiedź „hipoteka zabezpieczająca inną wierzytelność” nie powtarza ustawowej kategorii „wierzytelność zabezpieczona hipoteką”. Klucz wymaga korekty lub oficjalnego wyjaśnienia.')
a([209,245],'Zwykłe nabycie działki na budownictwo mieszkaniowe nie jest samo w sobie wskazanym w art. 6 UGN celem publicznym. Nie należy utożsamiać potrzeby społecznej z ustawową kategorią uprawniającą do wywłaszczenia.','ugn:6',caveat='Niektóre przedsięwzięcia mieszkaniowe mogą podlegać odrębnym ustawom. Odpowiedź dotyczy ogólnego, nieuszczegółowionego celu opisanego w pytaniu.')
a([213,327],'Odpowiedzialność zawodowa wiąże się z naruszeniem obowiązków wykonywania zawodu. Odpowiedzialność cywilna może polegać na naprawieniu szkody, a karna powstaje dopiero po spełnieniu znamion konkretnego przestępstwa. Te reżimy mogą się zbiegać.','ugn:178','kc:415',caveat='Samo wykonanie wadliwej wyceny nie oznacza automatycznie przestępstwa. Nie przypisano abstrakcyjnie jednego przepisu karnego do każdej wyceny.')
a([224],'Walne zgromadzenie jest organem najwyższym: obejmuje członków spółdzielni i podejmuje zastrzeżone uchwały. Zarząd prowadzi sprawy spółdzielni, a rada nadzorcza sprawuje kontrolę; nie zastępują walnego jako organu najwyższego.','spoldz:36')
a([235,401],'Podobieństwo wymaga porównywalności położenia, stanu prawnego, przeznaczenia, sposobu korzystania i innych cech cenotwórczych. Dobór właściwego rynku służy temu, by ceny transakcyjne mogły rzeczywiście objaśniać wartość badanej nieruchomości.','ugn:4',caveat='Definicja nieruchomości podobnej nie oznacza sztywnej granicy administracyjnej rynku. Przydatność transakcji wymaga oceny merytorycznej.')
a([249],'Trzeba odróżnić ograniczenie sposobu korzystania z nieruchomości dla infrastruktury od krótkiego zajęcia w sytuacji nagłej szkody. Dla tego drugiego art. 126 UGN przewiduje limit sześciu miesięcy; nie wolno przenosić go mechanicznie na każdą inwestycję infrastrukturalną.','ugn:124','ugn:126',caveat='Sformułowanie o dowolnie uznaniowym okresie jest uproszczeniem: rozstrzygnięcie musi odpowiadać konkretnej podstawie i zakresowi ingerencji.')
a([280],'W sprawdzonym tekście jednolitym UGN punkt 14 art. 4, w którym dawniej mieściła się definicja standardów zawodowych, jest uchylony. Brak definicji w danej wersji ustawy nie oznacza, że termin nigdy nie był ustawowo zdefiniowany.','ugn:4',caveat='Pytanie jest zależne od daty. Nie należy odnosić dzisiejszego stanu definicji do wszystkich historycznych egzaminów.')
a([353],'Zwrot obejmuje nieruchomość lub część zbędną na cel wywłaszczenia po spełnieniu ustawowych przesłanek. Wymaga odpowiedniego postępowania i rozliczenia odszkodowania; samo niezabudowanie fragmentu nie przesądza bezwarunkowo o zwrocie.','ugn:136','ugn:137','ugn:140',caveat='Słowo „bezwarunkowo” jest zbyt kategoryczne i nie oddaje warunków ustawowych.')
a([406],'Poręczyciel zobowiązuje się wykonać zobowiązanie, jeżeli nie wykona go dłużnik. Z reguły odpowiada jak współdłużnik solidarny, ale poręczenie pozostaje inną konstrukcją niż przejęcie długu.','kc:876','kc:881','kc:519',caveat='Odpowiedź utożsamiająca poręczenie z przejęciem długu wymaga sprawdzenia. Przejęcie długu ma odrębne przesłanki i co do zasady zmienia osobę dłużnika.')
a([466],'Rzeczoznawca ma wykonywać czynności zgodnie z prawem, szczególną starannością i zasadą bezstronności oraz stale doskonalić kwalifikacje. Odwołanie do standardów zawodowych trzeba oceniać według brzmienia ustawy obowiązującego w danym okresie.','ugn:175',caveat='Sprawdzony tekst UGN nie zawiera w art. 175 ust. 1 dawnego wyraźnego nakazu stosowania standardów zawodowych. Klucz ma cechę historyczną.')
a([481,709],'Działka ewidencyjna jest jednostką geodezyjną, a nieruchomość przedmiotem prawa własności. Jedna nieruchomość może obejmować kilka działek; ich sąsiedztwo lub położenie w tym samym obrębie nie rozstrzygają samodzielnie o jedności prawnej.','ugn:4','kw:21',caveat='W pytaniu o odrębnie położone działki brakuje informacji o właścicielu, księdze i podstawie połączenia. Sama zgodność obrębu lub jednostki ewidencyjnej nie wystarcza.')
a([495],'Po przedterminowym rozwiązaniu użytkowania wieczystego zwraca się opłaty roczne już wniesione za niewykorzystany okres, z waloryzacją i ustawowym limitem. Nie jest to wynagrodzenie za sam fakt niewykorzystania przyszłych lat.','ugn:33',caveat='Brak opłaty za rok rozwiązania nie jest w przywołanym przepisie ogólną podstawą utraty całego zwrotu. Pierwsza zaznaczona odpowiedź wymaga weryfikacji.')
a([553],'Art. 173a UGN dotyczy okresowych badań rynku przez ministra. W sprawdzonym tekście jego ust. 2 jest uchylony, dlatego dawnych obowiązków przekazywania danych nie można uzasadniać samym aktualnym numerem tej jednostki.','ugn:173a',caveat='Pytanie wymaga odtworzenia historycznego brzmienia przepisu z daty egzaminu.')
a([566],'Zasadą jest oddawanie gruntów Skarbu Państwa państwowym jednostkom organizacyjnym, a gruntów samorządowych odpowiednim jednostkom samorządowym. Ustawa dopuszcza wyjątki wynikające z odrębnych przepisów.','ugn:43',caveat='Druga odpowiedź odwołuje się do historycznej organizacji zadań melioracyjnych. Nie potwierdzono jej dla wszystkich dat egzaminów.')
a([634],'Osobą będącą członkiem spółdzielni mieszkaniowej może być osoba fizyczna albo, w przewidzianych przypadkach, osoba prawna. Dla osoby prawnej ustawa wyklucza lokatorskie prawo do lokalu; warunki członkostwa wynikają przede wszystkim z ustawy.','spoldzielnie:3',caveat='Sformułowanie „z ograniczeniami wynikającymi ze statutu” jest zbyt ogólne wobec ustawowych zasad członkostwa i zmian przepisów.')
a([661],'Wpis jest konstytutywny, gdy dopiero z jego dokonaniem powstaje prawo lub następuje jego przeniesienie. Takie znaczenie ma wpis ustanowienia odrębnej własności lokalu i hipoteki; dla użytkowania wieczystego znaczenie wpisu wynika również z przepisów szczególnych.','lokale:7','kw:67',caveat='Należy odróżnić ustanowienie i przeniesienie prawa od ujawnienia prawa nabytego z mocy ustawy. Nie każdy wpis dotyczący wskazanych praw ma zawsze charakter prawotwórczy.')
a([666],'Art. 98a UGN wyznacza trzyletni termin na wszczęcie postępowania po ostatecznym podziale. Jest to inna kwestia niż data wydania decyzji kończącej wszczęte postępowanie.','ugn:98a',caveat='Odpowiedź o braku terminu wydania decyzji odnosi się do szczególnego terminu materialnego; organ nadal obowiązują ogólne zasady terminowego prowadzenia postępowania.')
a([674],'Wyjątki od gminnego pierwokupu obejmują m.in. sprzedaż osobie bliskiej i ustawowo wskazane nabycia rekompensacyjne. Przy nieruchomości zabytkowej skorzystanie z tego szczególnego prawa wymaga jego ujawnienia w księdze wieczystej.','ugn:109',caveat='Wyjątki trzeba odczytywać z całego art. 109, wraz z zakresem nieruchomości i przesłankami poszczególnych punktów.')
a([743],'Obecne przepisy odróżniają ustanawianie prawa odrębnej własności od obrotu istniejącym spółdzielczym własnościowym prawem do lokalu. Możliwość zbycia już istniejącego prawa nie oznacza możliwości tworzenia nowych praw tego rodzaju przez przekształcenie lokatorskiego.','spoldzielnie:12','spoldzielnie:17_2',caveat='Zakaz tworzenia nowych praw wynika także z przepisów nowelizujących i przejściowych. Nie wskazano tu pełnej historycznej podstawy zakazu.')
# Inwestycje drogowe: sprawdzony oficjalny tekst z 2024 r.
a([83,430],'Specustawa drogowa przewiduje wydanie ZRID w terminie 90 dni od złożenia wniosku właściwego zarządcy drogi. To termin dla organu, nie okres oczekiwania liczony dopiero od ostateczności innej decyzji.','drogi:11a')
a([155,226,281],'Po wygaśnięciu hipoteki odszkodowanie odpowiada świadczeniu głównemu zabezpieczonej wierzytelności oraz odsetkom zabezpieczonym tą hipoteką. Kwotę zalicza się na spłatę tego zadłużenia, aby wierzyciel nie uzyskał podwójnego zaspokojenia.','drogi:18')
a([257],'Z ostatecznością ZRID wygasają ograniczone prawa rzeczowe na przejmowanej nieruchomości lub jej użytkowaniu wieczystym. Użytkowanie wieczyste gruntu publicznego przeznaczonego na pas drogowy również wygasa w ustawowym trybie.','drogi:12')
a([261],'Ograniczenie obrotu gruntami Skarbu Państwa i samorządowymi objętymi wnioskiem wiąże się z zawiadomieniem o wszczęciu postępowania ZRID. Ma zabezpieczyć możliwość przeprowadzenia inwestycji przed zmianami stanu prawnego w toku sprawy.','drogi:11d')
a([288,478,660],'Ustawowa premia za terminowe wydanie nieruchomości wynosi 5% wartości nieruchomości albo użytkowania wieczystego. Wymaga spełnienia przesłanek wydania, a przy zabudowie również opróżnienia lokalu i pomieszczeń, w terminie wskazanym w specustawie.','drogi:18',caveat='Termin 30 dni może być liczony od różnych zdarzeń procesowych wskazanych w art. 18 ust. 1e, nie wyłącznie od ostateczności ZRID.')
a([304],'Dodatkowe 10 000 zł przysługuje w przewidzianej ustawą sytuacji dotychczasowemu właścicielowi lub użytkownikowi wieczystemu zamieszkałemu w objętym ZRID budynku lub lokalu mieszkalnym. Dodatek wiąże się z koniecznością opuszczenia miejsca zamieszkania.','drogi:18')
a([305],'Odszkodowanie może przysługiwać właścicielowi, użytkownikowi wieczystemu oraz uprawnionemu z ograniczonego prawa rzeczowego. Utrata każdego z tych praw ma własny zakres rozliczenia; suma świadczeń podlega zasadom specustawy.','drogi:12','drogi:18')
a([310],'ZRID po uzyskaniu ostateczności przenosi wskazane nieruchomości z mocy prawa na Skarb Państwa albo właściwą jednostkę samorządu. Nie potrzeba dodatkowej umowy sprzedaży przenoszącej własność.','drogi:12')
a([373],'Jedna decyzja ZRID łączy rozstrzygnięcia lokalizacyjne i podziałowe oraz wywołuje ustawowe skutki dotyczące własności wskazanych nieruchomości. Nie oznacza to przejęcia całej pierwotnej działki, jeżeli pas drogowy obejmuje tylko jej część.','drogi:11f','drogi:12')
a([448,591],'Decyzję określającą odszkodowanie wydaje organ, który wydał ZRID. Właściwość jest więc związana z organem prowadzącym inwestycję drogową, a nie automatycznie z każdym organem gospodarującym zasobem.','drogi:12')
a([597],'Zarząd drogi sprawuje nieodpłatny trwały zarząd gruntami pasa drogowego. Jest to ustawowy tytuł władania służący wykonywaniu zadań drogowych, różny od przeniesienia własności gruntu na jednostkę organizacyjną.','drogipub:22','ugn:43')
a([691],'Drogi wewnętrzne pozostają poza ustawowymi kategoriami dróg publicznych. Obecna definicja obejmuje także wskazane parkingi i place przeznaczone do ruchu, o ile nie leżą w pasie drogowym drogi publicznej.','drogipub:8')
# Środowisko i ochrona własności.
a([29],'Strefa przemysłowa pozwala w ustawowo określonych warunkach uregulować oddziaływania instalacji na wyznaczonym terenie. Przepis wiąże jej utworzenie z wnioskiem władającego powierzchnią ziemi objętą strefą.','pos:136b',caveat='Samo złożenie wniosku nie wystarcza; muszą być spełnione materialne i proceduralne przesłanki ustanowienia strefy.')
a([30],'W sprawach ograniczeń związanych z ochroną zasobów środowiska, do których odsyła art. 130, odszkodowanie ustala właściwy starosta w drodze decyzji na żądanie poszkodowanego. Nie należy mylić tego trybu z odszkodowaniem za obszar ograniczonego użytkowania.','pos:130','pos:131')
a([123,196],'Obszar ograniczonego użytkowania może służyć wskazanym w ustawie rodzajom instalacji i obiektów, gdy mimo zastosowanych rozwiązań nie można dotrzymać standardów jakości środowiska poza ich terenem. Katalog obejmuje m.in. oczyszczalnie, składowiska, kompostownie, trasy komunikacyjne oraz linie i stacje elektroenergetyczne.','pos:135')
a([138,528],'Właściciel może żądać odszkodowania za szkodę związaną z ograniczeniem korzystania. Roszczenie odszkodowawcze przysługuje także użytkownikowi wieczystemu i osobie mającej inne prawo rzeczowe; szkoda może obejmować spadek wartości nieruchomości.','pos:129')
a([346],'W sporach odszkodowawczych wynikających z utworzenia obszaru ograniczonego użytkowania właściwe są sądy powszechne. Tego trybu nie należy utożsamiać z decyzją starosty dla ograniczeń ochrony zasobów środowiska z art. 130.','pos:136','pos:131')
a([564],'Jeżeli ograniczenie uniemożliwia lub istotnie ogranicza dotychczasowe zgodne korzystanie, właściciel może domagać się wykupu nieruchomości lub jej części. Odszkodowanie dotyczy natomiast poniesionej szkody, w tym zmniejszenia wartości.','pos:129')
a([565],'Obszar cichy w aglomeracji jest ustawowo powiązany z brakiem przekroczeń dopuszczalnego poziomu hałasu. Nie oznacza całkowitej ciszy ani braku jakiejkolwiek działalności na danym terenie.','pos:3')
# Przekształcenie oraz rekompensaty.
a([65],'Ustawa z 2005 r. przewiduje zasadę odpłatnego przekształcenia i ustawowe wyjątki od odpłatności. Nie należy utożsamiać tego trybu decyzji z powszechnym przekształceniem gruntów mieszkaniowych na podstawie późniejszej ustawy.','uw2005:4','uw2005:5',caveat='Podlinkowano tekst pierwotny; zakres uprawnionych, bonifikat i wyjątków zmieniał się w kolejnych nowelizacjach.')
a([329],'W trybie ustawy z 2005 r. przekształcenie następowało na podstawie ostatecznej decyzji właściwego organu. Ustawa z 2018 r. przewidziała inną konstrukcję: ustawowy skutek potwierdzany zaświadczeniem.','uw2005:3','uw2018:4')
a([128],'Opłaty roczne podlegają ustawowej waloryzacji. Wniesienie całej opłaty jednorazowej zamyka natomiast obowiązek wnoszenia pozostającej do spłaty kwoty; nie pozostawia przyszłych rat do dalszej waloryzacji.','uw2018:7','uw2018:10',caveat='Źródło zawiera pierwotne brzmienie z 2018 r.; szczegółowy tryb i częstotliwość waloryzacji wymagają sprawdzenia wersji właściwej dla egzaminu.')
a([158],'Właściciel może zgłosić na piśmie zamiar jednorazowego wniesienia opłaty w każdym czasie trwania obowiązku jej płacenia. Opłata jednorazowa obejmuje kwotę pozostałą do spłaty według ustawowych zasad.','uw2018:7')
a([415],'Zaświadczenie potwierdza skutek przekształcenia wynikający z ustawy i stanowi podstawę ujawnienia własności w księdze oraz ewidencji. Nie jest konstytutywną decyzją przekształcającą stosowaną w dawnym trybie.','uw2018:4')
a([156],'Prawo do rekompensaty łączy się z pozostawieniem nieruchomości wskutek okoliczności wojennych i powojennych określonych ustawą oraz spełnieniem wymogów obywatelstwa. Warunki należy oceniać łącznie, a nie wybierać tylko jednego z nich.','zabug:1','zabug:2',caveat='Warunek zamieszkiwania 1 września 1939 r. był przedmiotem zmian i kontroli konstytucyjnej. Pierwotnego brzmienia nie należy bezpośrednio stosować do każdego historycznego egzaminu.')
a([176],'Pozytywna ocena przedstawionych dowodów następuje w formie postanowienia wojewody, które otwiera dalszy etap postępowania. Nie jest jeszcze ostatecznym przyznaniem i wypłatą świadczenia.','zabug:7')
a([606],'Po śmierci właściciela uprawnienie może przysługiwać jego spadkobiercom, z uwzględnieniem ustawowych warunków. Wskazanie części spadkobierców wymaga przewidzianych ustawą oświadczeń pozostałych.','zabug:3')
a([244],'Stowarzyszenie ogrodowe może nabyć grunt publiczny na własność albo uzyskać użytkowanie lub użytkowanie wieczyste. Ustawowy cel to założenie i prowadzenie rodzinnego ogrodu działkowego; tytuły te nie są ze sobą tożsame.','rod:9')
a([570],'Działkowiec otrzymuje odszkodowanie za należące do niego nasadzenia, urządzenia i obiekty. Ustawa przewiduje także odrębne rozliczenie prawa do działki oraz majątku stowarzyszenia, dlatego trzeba ustalić, kto jest właścicielem danego składnika.','rod:22')
a([687],'Dla osoby fizycznej kryterium bycia cudzoziemcem jest brak obywatelstwa polskiego. Samo zezwolenie na pobyt stały nie nadaje polskiego obywatelstwa, choć może mieć znaczenie dla zwolnień od obowiązku zezwolenia na zakup.','cudzoziemcy:1')
# Leśnictwo, rolnictwo i klasyfikacje techniczne.
a([9,714],'Właściwość zależy od rodzaju i położenia gruntu: sprawy gruntów rolnych należą zasadniczo do starosty, leśnych do dyrektora RDLP, a na obszarze parku narodowego do dyrektora parku. Wyłączenie z produkcji trzeba odróżnić od wcześniejszego przeznaczenia terenu w planie.','r-ochrona-gruntow:5','r-ochrona-gruntow:11')
a([31,200,254,624],'Grubizna jest kategorią surowca drzewnego wyznaczaną średnicą: w przyjętej w pytaniu konwencji co najmniej 5 cm bez kory lub 7 cm z korą. Rozróżnienie pomiaru z korą i bez niej jest istotne; tych progów nie stosuje się zamiennie do jednego pomiaru.',caveat='To definicja techniczna stosowana w leśnictwie i normowaniu surowca, a nie samodzielna reguła wyceny wynikająca z ustawy.')
a([33],'Halizna opisuje powierzchnię leśną wymagającą odnowienia, której nie zalicza się do prawidłowo odnowionego drzewostanu. Klucz obejmuje zarówno utrzymujący się brak drzewostanu, jak i bardzo słabo zadrzewione najmłodsze pokolenie.',caveat='Dokładne progi i okresy zależą od instrukcji urządzeniowej. Nie potwierdzono tu konkretnej wersji instrukcji obowiązującej na dzień egzaminu.')
a([34,460],'Mapa glebowo-rolnicza przedstawia właściwości gleb istotne dla rolnictwa, w tym oznaczenia ich typów i podłoża. Umożliwia odróżnienie gleb mineralnych od organicznych. Sam symbol klasy bonitacyjnej nie wystarcza do takiego rozróżnienia.')
a([80],'Młody drzewostan, który nie osiągnął wartości użytkowej odpowiedniej do pozyskania drewna, może być oceniany przez koszty jego założenia i pielęgnacji. Przy szkodzie trzeba ustalić także jej zakres, wiek i stan drzewostanu.','ugn:135',caveat='Art. 135 ust. 5 UGN dotyczy szczególnego kontekstu odszkodowania i nie ustanawia automatycznej metody każdej prywatnej szkody. Sam wiek 15 lat nie rozstrzyga wszystkich warunków wyceny.')
a([81,323,473],'Pierśnica jest średnicą pnia mierzoną na wysokości 1,3 m nad gruntem. Nie jest obwodem: dla przekroju kołowego obwód wynosi π × pierśnica. Wraz z wysokością drzewa i modelem kształtu pnia służy do szacowania miąższości.')
a([82,201],'Ziemniak gromadzi materiał zapasowy w podziemnej bulwie pędowej, a burak cukrowy w zgrubiałym korzeniu. Obie uprawy zalicza się do okopowych, choć ich użytkowe organy mają inną budowę botaniczną.')
a([199],'Drągowina to faza rozwoju młodego drzewostanu po tyczkowinie, w której pnie osiągają wymiary drobnych i średnich sortymentów. Nazwa opisuje etap wzrostu i możliwe produkty, a nie osobny gatunek drzewa.')
a([220],'Wskazane granice opisują sortyment średniowymiarowy: sprawdza się średnicę cieńszego końca oraz dopuszczalną średnicę dolną. Granice 5 i 24 cm dotyczą pomiaru bez kory w konwencji przyjętej w pytaniu.',caveat='Wymagania sortymentów ustalają normy i warunki techniczne. Nie potwierdzono konkretnej edycji normy; nie jest to uniwersalna ustawowa definicja.')
a([277],'Owocem rzepaku jest łuszczyna, suchy owoc pękający zawierający nasiona. Nasiona stanowią surowiec olejarski, ale botaniczną nazwą całego owocu jest łuszczyna, nie bulwa ani strąk.')
a([411,533,671],'Opis taksacyjny łączy informacje o siedlisku i drzewostanie: gatunkach, wieku, wymiarach, zadrzewieniu i miąższości. Dzięki temu służy planowaniu gospodarki leśnej i ocenie zasobów, a nie tylko ewidencji powierzchni.')
a([428],'Płazowina oznacza bardzo luźno porośniętą powierzchnię leśną. W kluczu próg zadrzewienia wynosi 0,3 dla II klasy wieku oraz 0,2 dla klas starszych; od wieku zależy więc granica tej kategorii.',caveat='To klasyfikacja urządzeniowa. Nie potwierdzono konkretnej edycji instrukcji określającej progi; komentarz nie zastępuje sprawdzenia normy z daty egzaminu.')
a([589],'Miąższość to objętość drewna, dlatego wyraża się ją w m³. Szacunek dla stojącego drzewa można uzyskać z tablic lub wzoru wykorzystującego wymiary i współczynnik kształtu; średnica sama nie wystarcza do obliczenia objętości.')
a([590],'Spośród typowych wymienianych zbóż pszenica ma wysokie wymagania glebowe: wymaga odpowiedniej zasobności, struktury i gospodarki wodnej. Sama klasa gleby nie gwarantuje plonu, bo znaczenie mają również odmiana, klimat i agrotechnika.')
a([750],'Oddział jest podstawową jednostką podziału powierzchniowego lasu, służącą orientacji, ewidencji i organizacji prac. W jego granicach wydziela się mniejsze pododdziały różniące się cechami drzewostanu lub siedliska.')
a([276,322,532,647],'Własność Skarbu Państwa nie oznacza, że każdy las pozostaje w zarządzie Lasów Państwowych. Ustawa przewiduje wyłączenia związane m.in. z parkami narodowymi i Zasobem Własności Rolnej; tytuł właścicielski i forma zarządu to różne zagadnienia.','r-lasy:4',caveat='Organizacja parków narodowych i ich tytuły do nieruchomości zmieniały się. Nie należy zakładać jednego sposobu władania dla wszystkich dat i wszystkich lasów państwowych.')
a([370],'Ustawowy pierwokup KOWR chroni obrót nieruchomością nabytą wcześniej z Zasobu: przy sprzedaży w ciągu pięciu lat może wejść w miejsce kupującego na rzecz Skarbu Państwa. To inna instytucja niż pierwszeństwo dzierżawcy przy pierwotnej sprzedaży z Zasobu.','r-gnr-sp:29')
a([182],'Dla sklasyfikowanych zadrzewień klucz stosuje połowę wskaźnika odpowiadającego klasie gruntu: 0,29 × 50% = 0,145. Dla gruntu bez klasyfikacji przewiduje odrębny sposób przypisania wskaźnika, więc nie wolno automatycznie zastosować tej samej połowy.',caveat='To zadanie o historycznej tabeli i regułach metody wskaźników szacunkowych. Samo działanie 0,29/2 nie potwierdza doboru tabeli ani wyniku dla gruntów niesklasyfikowanych.')
a([238],'Wskaźnik dla zadrzewień odwołuje się do rolniczej wartości gruntu. Okręg podatkowy i klasa bonitacyjna wskazują właściwe pole tabeli; potem stosuje się przewidziane w metodyce korekty.',caveat='Trzeba odróżnić tabelę wskaźników szacunkowych używaną do wyceny od ustawowej kwoty podatku rolnego.')
a([382,455],'W metodzie wskaźników szacunkowych cechy gruntu i warunki gospodarowania uzasadniają korekty wartości tabelarycznej. Struktura użytków jest istotna dla gospodarowania gruntami rolnymi, a szkody od szkodników mogą wpływać na wartość i użyteczność lasu.',caveat='Lista czynników i sposób ich uwzględnienia zależą od obowiązującego rozporządzenia i rodzaju wycenianej nieruchomości.')
a([501],'W historycznej metodzie wskaźnikowej sad wycenia się w części gruntowej według klasy gleby, na której go założono. Wartość drzew owocowych jest odrębnym zagadnieniem i nie powinna być ukryta w samym wskaźniku gruntu.')
a([627,669],'Klasy bonitacyjne gruntów ornych obejmują I, II, IIIa, IIIb, IVa, IVb, V i VI; litery a oraz b rozdzielają jakość klas III i IV. Symbol VIz występuje w historycznych klasyfikacjach gruntów najsłabszych.',caveat='Klucz zawiera VIz. Nie należy bez sprawdzenia wersji klasyfikacji przenosić historycznego oznaczenia do dzisiejszego katalogu klas.')
a([629,646],'Dla łąk i pastwisk stosuje się klasy od I do VI. W przeciwieństwie do gruntów ornych klasy III i IV nie są tu dzielone na a i b; porównywanie symboli różnych użytków wymaga uwzględnienia tej różnicy.')
a([670],'Zadrzewienia odróżnia się od lasu według rodzaju pokrycia, funkcji i kryteriów ewidencyjnych. Mogą obejmować drzewa i krzewy przy drogach oraz na gruntach niebędących lasem.',caveat='Podana w kluczu powierzchnia poniżej 0,1 ha nie jest samodzielnym, uniwersalnym warunkiem wszystkich ustawowych definicji zadrzewienia. Pytanie miesza opis przestrzenny i klasyfikację historyczną.')
a([320],'Użytek ekologiczny jest jedną z indywidualnych form ochrony przyrody. Ustanowienie następuje uchwałą rady gminy, która określa chroniony przedmiot, położenie i zasady ochrony.','r-ochrona-przyrody:44')
a([713],'Zwolnienie z opłaty i brak obowiązku uzyskania zezwolenia to różne mechanizmy. Krzewy do 25 m² mogą korzystać z wyłączenia zezwolenia, natomiast zwolnienie dotyczące 50 m² ma odrębnie określony cel przywrócenia użytkowania.','r-ochrona-przyrody:83f','r-ochrona-przyrody:86',caveat='Sprawdzony art. 86 ust. 1 pkt 8 mówi o użytkowaniu innym niż rolnicze. Odpowiedź łącząca 50 m² z celem rolniczym nie odtwarza tego przepisu; trzeba zbadać inne wyłączenie lub historyczne brzmienie.')
a([347],'Wzór zestawia wskaźniki wartości drzewostanu, stopień zadrzewienia, powierzchnię oraz cenowy przelicznik. Służy szczególnemu odszkodowaniu za przedwczesny wyrąb przy wyłączeniu lasu z produkcji, a nie zwykłemu wyliczeniu ceny sprzedawanego drewna.',caveat='Znaczenie każdego symbolu musi odpowiadać tabelom i rozporządzeniu właściwemu dla daty wyceny; bez nich nie można podstawiać dowolnych danych.')
# Planowanie, ewidencja i formy dokumentów.
a([299],'Miejscowy plan ustala przeznaczenie terenu i zasady zagospodarowania. Przy braku planu ustawowo wskazane inwestycje lokalizuje się w drodze odpowiednich decyzji; nie oznacza to jednak, że decyzja jest planem miejscowym.','p-upzp2024:4')
a([342],'Plan miejscowy wyznacza rozmieszczenie inwestycji celu publicznego, a przy jego braku właściwa decyzja lokalizacyjna może określić warunki dla konkretnego zamierzenia. Dawne studium przedstawiało politykę przestrzenną gminy, lecz samo nie było aktem prawa miejscowego.','p-upzp:4','p-upzp:9','p-upzp:10',caveat='System studium jest zastępowany planem ogólnym; należy uwzględnić przepisy przejściowe i datę egzaminu.')
a([345],'Opłata planistyczna jest procentem wzrostu wartości wywołanego uchwaleniem lub zmianą planu. Potrzebne są więc dwie wartości porównawcze i stawka z planu; opłata nie jest procentem całej ceny sprzedaży.','p-upzp:36','p-upzp:37')
a([425,515],'Wójt, burmistrz albo prezydent miasta ustala opłatę planistyczną decyzją administracyjną w ustawowym trybie. Rada gminy określa stawkę procentową w planie, ale nie wydaje indywidualnej decyzji o kwocie.','p-upzp:37')
a([471],'Pytanie dotyczy szczególnego ograniczenia możliwości stwierdzenia nieważności decyzji lokalizacyjnej po upływie 12 miesięcy od doręczenia lub ogłoszenia. Nie jest to zwykły termin wniesienia odwołania.','p-upzp:53',caveat='Należy sprawdzić właściwe brzmienie przepisu i skutki innych podstaw nadzwyczajnej kontroli decyzji; upływ terminu nie oznacza, że każda wadliwość znika.')
a([514],'Dostęp może być bezpośredni z drogi publicznej, przez drogę wewnętrzną albo za pośrednictwem odpowiedniej służebności. Trzeba badać rzeczywistą i prawną możliwość korzystania z dojazdu, a nie tylko bliskość drogi na mapie.','p-upzp:2')
a([251],'Powierzchnię użytkową lokalu zapisuje się w metrach kwadratowych z dokładnością do dwóch miejsc po przecinku, czyli 0,01 m². Precyzja zapisu danych nie jest tym samym co dopuszczalny błąd pomiaru lub zasady zaokrąglania poszczególnych pomieszczeń.')
a([273],'Symbol N oznacza nieużytki. To, do jakiej grupy ewidencyjnej je zaliczano, zależy od wersji rozporządzenia; nie wolno z potocznego znaczenia „rolny” wnioskować o uprawie ani o opodatkowaniu.',caveat='Klucz odwołuje się do klasyfikacji historycznej. Wymaga zestawienia z datą obowiązywania właściwego rozporządzenia EGiB.')
a([301],'Br to symbol gruntów rolnych zabudowanych. Oznacza kategorię użytku gruntowego, a nie osobną klasę bonitacyjną ani symbol samego budynku. Oznaczenie może współwystępować z informacją o klasie gleby.')
a([392,445,490],'Jednostka rejestrowa porządkuje obiekty ewidencji według ich położenia i zgodności praw. Dla gruntów istotne są granice obrębu i wspólna sytuacja prawna; odrębne zasady odnoszą się do budynków stanowiących osobne nieruchomości oraz lokali.',caveat='Przepisy i nazwy jednostek rejestrowych zmieniały się. „Identyczne prawa” należy czytać według rozporządzenia z danego okresu, a nie utożsamiać jedynie z nazwiskiem właściciela.')
a([409],'Mapa zasadnicza przedstawia przestrzenne położenie obiektów topograficznych i sieci uzbrojenia terenu wraz z atrybutami. Nie ogranicza się do podziemnych przewodów; obejmuje kategorie obiektów określone ustawą i przepisami wykonawczymi.','p-pgik:2')
a([531],'Rejestr cen nieruchomości należy do powiatowych zadań geodezyjnych. Prowadzi go starosta wykonujący zadania z zakresu administracji rządowej; w mieście na prawach powiatu odpowiednie zadania wykonuje prezydent.','p-pgik:7d')
a([316,562],'Elektroniczny numer księgi ma trzy części: czteroznakowy kod wydziału, ośmiocyfrowy numer księgi i cyfrę kontrolną, rozdzielone ukośnikami. Zapis LD1M/00002532/8 odpowiada temu schematowi.',caveat='Zgodność formatu nie dowodzi, że podany numer istnieje, ani że cyfra kontrolna została poprawnie obliczona.')
a([555],'Dokument ustanawiający własność, np. akt notarialny albo orzeczenie, trzeba odróżnić od dokumentów służących oznaczeniu lokalu w księdze. Dane opisowe są powiązane z właściwymi dokumentami ewidencji gruntów i budynków.','kw:26',caveat='Wskazanie wszystkich trzech odpowiedzi wymaga rozdzielenia podstawy wpisu prawa od podstawy oznaczenia nieruchomości; nie są to zawsze zamienne dokumenty.')
a([47,720],'Jednostka taksacyjna grupuje przedmiot masowej wyceny w sposób zapewniający jednorodność istotną dla wartości. Grunt może wymagać podziału według różnego przeznaczenia, a budynki lub lokale stanowią odrębne przedmioty ustalania wartości części składowych.','ugn:164','ugn:165',caveat='Szczegółowy zakres jednostki taksacyjnej wynika z przepisów wykonawczych o powszechnej taksacji. Nie potwierdzono tu pełnego zakresu wszystkich oznaczonych odpowiedzi.')
a([264],'Strefa taksacyjna służy grupowaniu obszarów o zbliżonych cechach wpływających na wartość. Jednorodność przeznaczenia i warunków rynkowych pozwala stosować wspólne parametry masowej wyceny.','ugn:164','ugn:166',caveat='Granice stref nie muszą odpowiadać granicom administracyjnym. Szczegółowy sposób ich wyznaczenia wymaga właściwych przepisów wykonawczych.')
a([172],'Projekt scalenia powinien odpowiadać przeznaczeniu i zasadom zagospodarowania określonym dla terenu. Nie można utożsamiać rolniczego scalenia i wymiany gruntów z odrębną procedurą scalenia i podziału nieruchomości z UGN.',caveat='W pytaniu chodzi o procedurę uregulowaną odrębną ustawą o scalaniu i wymianie gruntów; nie przypisano jej automatycznie przepisów UGN.')
a([174],'Prawo do lokalu oraz sam lokal mogą podlegać innym regułom amortyzacji podatkowej. Warunkiem dla wartości niematerialnej i prawnej było m.in. nabycie oraz gospodarcza przydatność prawa, ale zakres amortyzacji lokali mieszkalnych został później ograniczony.',caveat='Klucz ma charakter historyczny i jest zbyt ogólny bez wskazania rodzaju lokalu, podatku i daty. Nie można traktować go jako aktualnej zasady amortyzacji wszystkich praw do lokali.')
a([464],'W zadaniach uwłaszczeniowych rozdziela się datę stanu nieruchomości od daty cen przyjętych do określenia wartości. Dzień 5 grudnia 1990 r. jest historyczną datą nabycia praw przez określone osoby prawne.',caveat='Nie potwierdzono pełnej reguły ceny dla opisanego trybu decyzji. Bez wskazania konkretnej podstawy uwłaszczenia nie należy stosować automatycznie daty wydania decyzji jako daty wartości.')
a([496,535],'Prawo geologiczne i górnicze oddziela złoża objęte własnością górniczą od kopalin związanych z własnością gruntu. Sól kamienna jest wymieniona w katalogu własności górniczej Skarbu Państwa; pospolite piaski, żwiry i gliny co do zasady pozostają związane z gruntem.','o-geologia:10',caveat='Należy badać ustawową kategorię złoża i zakres przestrzenny prawa; samo potoczne określenie materiału nie rozstrzyga każdego przypadku.')
a([567],'Podatek od nieruchomości obejmuje m.in. budynki lub ich części. Trzeba jednak uwzględnić ustawowe wyłączenia i zwolnienia; samo istnienie obiektu nie przesądza jeszcze, że w każdej sytuacji powstaje podatek.')
a([416,754],'OC ma istnieć już przed rozpoczęciem wykonywania umowy o czynności rzeczoznawstwa: najpóźniej w dniu poprzedzającym rozpoczęcie. Nie wystarcza zawarcie polisy dopiero po wykonaniu operatu lub ujawnieniu szkody.','o-oc:3')
a([685],'Kwatery i kwatery internatowe służą ustawowym zadaniom zakwaterowania wojska, co odróżnia je od zbędnych lokali mieszkalnych możliwych do sprzedaży. Samo powierzenie lokalu Agencji nie oznacza automatycznie dopuszczalności zbycia.',caveat='Wyłączenia sprzedaży wymagają ustalenia kategorii lokalu według ustawy o zakwaterowaniu Sił Zbrojnych i wersji właściwej dla egzaminu; nie potwierdzono tu pełnej podstawy ustawowej.')
